{"title": "M365 compliance - findings matrix", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "One row per tenant, one column per compliance check. Green is zero findings.",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "timestamp",
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "scoped": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.m365.event_type": "tenant_summary"
                    }
                  }
                ]
              }
            },
            "aggs": {
              "tenant": {
                "terms": {
                  "field": "data.m365.tenant_name",
                  "size": 50
                },
                "aggs": {
                  "expired": {
                    "max": {
                      "field": "data.m365.skus_expired"
                    }
                  },
                  "critical": {
                    "max": {
                      "field": "data.m365.skus_expiring_critical"
                    }
                  },
                  "warning": {
                    "max": {
                      "field": "data.m365.skus_expiring_warning"
                    }
                  },
                  "exhausted": {
                    "max": {
                      "field": "data.m365.skus_pool_exhausted"
                    }
                  },
                  "overassigned": {
                    "max": {
                      "field": "data.m365.skus_overassigned"
                    }
                  },
                  "degraded": {
                    "max": {
                      "field": "data.m365.skus_service_plans_degraded"
                    }
                  },
                  "disabled": {
                    "max": {
                      "field": "data.m365.disabled_licensed_users"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.scoped.tenant.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.key",
      "as": "tenant"
    },
    {
      "calculate": "datum.expired.value == null ? 0 : datum.expired.value",
      "as": "Expired"
    },
    {
      "calculate": "datum.critical.value == null ? 0 : datum.critical.value",
      "as": "Renews <30d"
    },
    {
      "calculate": "datum.warning.value == null ? 0 : datum.warning.value",
      "as": "Renews <90d"
    },
    {
      "calculate": "datum.exhausted.value == null ? 0 : datum.exhausted.value",
      "as": "Pool full"
    },
    {
      "calculate": "datum.overassigned.value == null ? 0 : datum.overassigned.value",
      "as": "Over-assigned"
    },
    {
      "calculate": "datum.degraded.value == null ? 0 : datum.degraded.value",
      "as": "Plans degraded"
    },
    {
      "calculate": "datum.disabled.value == null ? 0 : datum.disabled.value",
      "as": "Disabled licensed"
    },
    {
      "fold": [
        "Expired",
        "Renews <30d",
        "Renews <90d",
        "Pool full",
        "Over-assigned",
        "Plans degraded",
        "Disabled licensed"
      ],
      "as": [
        "check",
        "findings"
      ]
    }
  ],
  "encoding": {
    "x": {
      "field": "check",
      "type": "nominal",
      "title": null,
      "sort": [
        "Expired",
        "Renews <30d",
        "Renews <90d",
        "Pool full",
        "Over-assigned",
        "Plans degraded",
        "Disabled licensed"
      ],
      "axis": {
        "labelAngle": -30,
        "orient": "top"
      }
    },
    "y": {
      "field": "tenant",
      "type": "nominal",
      "title": null,
      "axis": {
        "labelLimit": 220
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "stroke": "#fff",
        "strokeWidth": 2
      },
      "encoding": {
        "color": {
          "field": "findings",
          "type": "quantitative",
          "title": "Findings",
          "scale": {
            "type": "threshold",
            "domain": [
              1,
              3
            ],
            "range": [
              "#54B399",
              "#D6BF57",
              "#E7664C"
            ]
          }
        },
        "tooltip": [
          {
            "field": "tenant",
            "type": "nominal"
          },
          {
            "field": "check",
            "type": "nominal"
          },
          {
            "field": "findings",
            "type": "quantitative"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "fontSize": 13,
        "fontWeight": "bold"
      },
      "encoding": {
        "text": {
          "field": "findings",
          "type": "quantitative"
        },
        "color": {
          "value": "#1a1a1a"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": "transparent"
    },
    "axis": {
      "grid": false
    }
  }
}"}}

