{"title": "M365 compliance - pools with no headroom", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Free seats per SKU where none are left. Negative means more seats are assigned than were purchased.",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "timestamp",
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "scoped": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.m365.event_type": "license"
                    }
                  },
                  {
                    "term": {
                      "data.m365.license_class": "paid"
                    }
                  }
                ]
              }
            },
            "aggs": {
              "tenant": {
                "terms": {
                  "field": "data.m365.tenant_name",
                  "size": 50
                },
                "aggs": {
                  "sku": {
                    "terms": {
                      "field": "data.m365.sku_display_name",
                      "size": 60
                    },
                    "aggs": {
                      "usable": {
                        "max": {
                          "field": "data.m365.usable_units"
                        }
                      },
                      "assigned": {
                        "max": {
                          "field": "data.m365.assigned_units"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.scoped.tenant.buckets"
    }
  },
  "transform": [
    {
      "flatten": [
        "sku.buckets"
      ],
      "as": [
        "sku"
      ]
    },
    {
      "calculate": "datum.key",
      "as": "tenant"
    },
    {
      "calculate": "datum.sku.key",
      "as": "product"
    },
    {
      "calculate": "datum.sku.usable.value - datum.sku.assigned.value",
      "as": "headroom"
    },
    {
      "calculate": "datum.tenant + ' / ' + datum.product",
      "as": "label"
    },
    {
      "filter": "datum.headroom <= 0"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusEnd": 2
      },
      "encoding": {
        "color": {
          "condition": {
            "test": "datum.headroom < 0",
            "value": "#E7664C"
          },
          "value": "#D6BF57"
        },
        "tooltip": [
          {
            "field": "tenant",
            "type": "nominal"
          },
          {
            "field": "product",
            "type": "nominal"
          },
          {
            "field": "headroom",
            "type": "quantitative",
            "title": "Free seats"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#69707D"
      },
      "encoding": {
        "x": {
          "datum": 0
        }
      }
    }
  ],
  "encoding": {
    "y": {
      "field": "label",
      "type": "nominal",
      "title": null,
      "sort": "x",
      "axis": {
        "labelLimit": 300
      }
    },
    "x": {
      "field": "headroom",
      "type": "quantitative",
      "title": "Free seats (negative = over-assigned)"
    }
  },
  "config": {
    "view": {
      "stroke": "transparent"
    }
  }
}"}}

{"title": "M365 compliance - licences on disabled accounts", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Disabled accounts still holding a licence, and what share of the licensed population they are.",
  "data": {
    "url": {
      "%context%": true,
      "%timefield%": "timestamp",
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "scoped": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.m365.event_type": "tenant_summary"
                    }
                  }
                ]
              }
            },
            "aggs": {
              "tenant": {
                "terms": {
                  "field": "data.m365.tenant_name",
                  "size": 50,
                  "order": {
                    "disabled": "desc"
                  }
                },
                "aggs": {
                  "disabled": {
                    "max": {
                      "field": "data.m365.disabled_licensed_users"
                    }
                  },
                  "licensed": {
                    "max": {
                      "field": "data.m365.licensed_users"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.scoped.tenant.buckets"
    }
  },
  "transform": [
    {
      "calculate": "datum.key",
      "as": "tenant"
    },
    {
      "calculate": "datum.disabled.value == null ? 0 : datum.disabled.value",
      "as": "disabled"
    },
    {
      "calculate": "datum.licensed.value",
      "as": "licensed"
    },
    {
      "calculate": "datum.licensed.value > 0 ? 100 * datum.disabled.value / datum.licensed.value : 0",
      "as": "share"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusEnd": 2
      },
      "encoding": {
        "color": {
          "field": "disabled",
          "type": "quantitative",
          "title": "Licences",
          "scale": {
            "type": "threshold",
            "domain": [
              1,
              3
            ],
            "range": [
              "#54B399",
              "#D6BF57",
              "#E7664C"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "tenant",
            "type": "nominal"
          },
          {
            "field": "disabled",
            "type": "quantitative",
            "title": "Disabled but licensed"
          },
          {
            "field": "licensed",
            "type": "quantitative"
          },
          {
            "field": "share",
            "type": "quantitative",
            "title": "% of licensed",
            "format": ".2f"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 6,
        "fontSize": 11,
        "color": "#343741"
      },
      "encoding": {
        "text": {
          "field": "share",
          "type": "quantitative",
          "format": ".2f"
        }
      }
    }
  ],
  "encoding": {
    "y": {
      "field": "tenant",
      "type": "nominal",
      "title": null,
      "sort": "-x",
      "axis": {
        "labelLimit": 220
      }
    },
    "x": {
      "field": "disabled",
      "type": "quantitative",
      "title": "Disabled accounts holding a licence"
    }
  },
  "config": {
    "view": {
      "stroke": "transparent"
    }
  }
}"}}

